def solve(I):
    g=[row[:] for row in I]; H,W=len(g),len(g[0])
    band=[r for r in range(H) if all(x==3 for x in g[r])]
    if not band and any(all(x==3 for x in g[c]) for c in range(W)):
        band=[c for c in range(W) if all(g[r][c]==3 for r in range(H))]
        horizontal=False
    else:
        horizontal=True
    # erase band
    if horizontal:
        for r in band:
            for c in range(W):
                if g[r][c]==3: g[r][c]=0
    else:
        for c in band:
            for r in range(H):
                if g[r][c]==3: g[r][c]=0
    return g,band,horizontal,H,W
